ALTER TABLE `group` ADD `from_organization_id` text;--> statement-breakpoint
CREATE INDEX `idx_group_from_organization` ON `group` (`from_organization_id`);--> statement-breakpoint
-- Every outside act, and any listing with a contact on it, becomes a performer organization. One a member or band now owns is archived.
INSERT INTO `organization` (`id`, `name`, `directory_entry_id`, `archived_at`) SELECT lower(hex(randomblob(16))), de.`name`, de.`id`, CASE WHEN de.`user_id` IS NULL AND de.`group_id` IS NULL THEN NULL ELSE unixepoch() END FROM `directory_entry` de WHERE ((de.`user_id` IS NULL AND de.`group_id` IS NULL) OR EXISTS (SELECT 1 FROM `contact` c WHERE c.`entry_id` = de.`id`)) AND NOT EXISTS (SELECT 1 FROM `organization` o WHERE o.`directory_entry_id` = de.`id`);--> statement-breakpoint
INSERT OR IGNORE INTO `party_role` (`id`, `organization_id`, `role`) SELECT lower(hex(randomblob(16))), o.`id`, 'performer' FROM `organization` o WHERE o.`directory_entry_id` IS NOT NULL;--> statement-breakpoint
UPDATE `contact` SET `organization_id` = (SELECT o.`id` FROM `organization` o WHERE o.`directory_entry_id` = `contact`.`entry_id`) WHERE `entry_id` IS NOT NULL AND `organization_id` IS NULL;--> statement-breakpoint
UPDATE `group` SET `from_organization_id` = (SELECT o.`id` FROM `organization` o JOIN `directory_entry` de ON de.`id` = o.`directory_entry_id` WHERE de.`group_id` = `group`.`id` LIMIT 1) WHERE `from_organization_id` IS NULL;--> statement-breakpoint
-- A set's typed contact becomes a contact row: one per address, reusing one already on file; the rest one per set.
INSERT INTO `contact` (`id`, `organization_id`, `name`, `email`, `phone`, `source`) SELECT lower(hex(randomblob(16))), min(o.`id`), min(nullif(trim(ps.`contact_name`), '')), lower(trim(ps.`contact_email`)), min(nullif(trim(ps.`contact_phone`), '')), 'staff_entered' FROM `production_slot` ps LEFT JOIN `event_band` eb ON eb.`id` = ps.`event_band_id` LEFT JOIN `organization` o ON o.`directory_entry_id` = eb.`directory_entry_id` WHERE trim(coalesce(ps.`contact_email`, '')) <> '' AND lower(trim(ps.`contact_email`)) NOT IN (SELECT `email` FROM `contact` WHERE `email` IS NOT NULL) GROUP BY lower(trim(ps.`contact_email`));--> statement-breakpoint
UPDATE `production_slot` SET `contact_id` = (SELECT c.`id` FROM `contact` c WHERE c.`email` = lower(trim(`production_slot`.`contact_email`)) ORDER BY c.`created_at`, c.`id` LIMIT 1) WHERE trim(coalesce(`contact_email`, '')) <> '';--> statement-breakpoint
INSERT INTO `contact` (`id`, `organization_id`, `name`, `phone`, `source`) SELECT 'slot-' || ps.`id`, o.`id`, nullif(trim(ps.`contact_name`), ''), nullif(trim(ps.`contact_phone`), ''), 'staff_entered' FROM `production_slot` ps LEFT JOIN `event_band` eb ON eb.`id` = ps.`event_band_id` LEFT JOIN `organization` o ON o.`directory_entry_id` = eb.`directory_entry_id` WHERE ps.`contact_id` IS NULL AND trim(coalesce(ps.`contact_name`, '') || coalesce(ps.`contact_phone`, '')) <> '';--> statement-breakpoint
UPDATE `production_slot` SET `contact_id` = 'slot-' || `id` WHERE `contact_id` IS NULL AND trim(coalesce(`contact_name`, '') || coalesce(`contact_phone`, '')) <> '';
